IF COL_LENGTH('cmms_auth.Users','Department') IS NULL ALTER TABLE cmms_auth.Users ADD Department nvarchar(50) NULL;
IF COL_LENGTH('cmms.WorkOrder','RequestDepartment') IS NULL ALTER TABLE cmms.WorkOrder ADD RequestDepartment nvarchar(50) NULL;
IF OBJECT_ID('inv.PartLoan') IS NULL CREATE TABLE inv.PartLoan(LoanID bigint IDENTITY PRIMARY KEY,PartID bigint NOT NULL REFERENCES inv.Part(PartID),WarehouseID int NOT NULL REFERENCES inv.Warehouse(WarehouseID),UserId varchar(24) NOT NULL,Username nvarchar(100) NOT NULL,Quantity decimal(18,4) NOT NULL CHECK(Quantity>0),Status varchar(16) NOT NULL DEFAULT 'BORROWED' CHECK(Status IN('BORROWED','RETURNED','USED')),BorrowedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),ResolvedAt datetime2 NULL,ResolvedBy nvarchar(100) NULL,Remark nvarchar(1000) NULL);
IF OBJECT_ID('cmms.TechnicianOvertime') IS NULL CREATE TABLE cmms.TechnicianOvertime(OvertimeID bigint IDENTITY PRIMARY KEY,UserId varchar(24) NOT NULL,Username nvarchar(100) NOT NULL,WorkDate date NOT NULL,Hours decimal(5,2) NOT NULL CHECK(Hours>0 AND Hours<=24),Remark nvarchar(1000) NULL,UpdatedBy nvarchar(100) NOT NULL,UpdatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),Version int NOT NULL DEFAULT 1);
IF NOT EXISTS(SELECT 1 FROM ref.InventoryTransactionType WHERE TypeCode='BORROW') INSERT ref.InventoryTransactionType(TypeCode,TypeName,QuantitySign) VALUES('BORROW',N'ยืมอะไหล่',-1);
IF NOT EXISTS(SELECT 1 FROM ref.InventoryTransactionType WHERE TypeCode='LOAN_RETURN') INSERT ref.InventoryTransactionType(TypeCode,TypeName,QuantitySign) VALUES('LOAN_RETURN',N'คืนจากการยืม',1);
